config.script:
# 1. Grab the selected tag path from your custom property
selected = self.view.custom.SelectedTag

# 2. Safely read the existing tags list as a true Python list
current = list(self.view.custom.Tags) if self.view.custom.Tags else []

# 3. Normalize single selection strings into a list
if isinstance(selected, basestring):
    selected = [selected]

# 4. Append new tags if they aren't duplicates
added_any = False
for tag in selected:
    if tag not in current and tag.strip() != "":
        current.append(tag)
        added_any = True

# 5. If changes were made, update the View and the Chart
if added_any:
    self.view.custom.Tags = current

    # Path navigating across the container layout to find the chart
    chart = self.getParent().getSibling("CoordinateContainer_0").getChild("FlexContainer").getChild("TimeSeriesChart")

    # Check if the chart component was successfully located
    if chart is not None:
        chart_plots = []

        # Loop through the tags to build the plots structure without hardcoded colors
        for t in current:
            tag_name = t.split("/")[-1] 

            chart_plots.append({
                "field": t,
                "label": tag_name,
                "type": "line",
                "axis": "Default",
                "style": {
                    "stroke": {
                        "width": 2  # Standard, clean line width
                    }
                }
            })

        # --- SAFE SERIES INJECTION ---
        # Checks if series[0] exists. If not, creates it dynamically to prevent IndexError.
        if len(chart.props.series) > 0:
            chart.props.series[0].plots = chart_plots
        else:
            new_series = {
                "name": "Trends",
                "plots": chart_plots
            }
            chart.props.series = [new_series]

    else:
        system.util.getLogger("TrendAddButton").warn("Could not find TimeSeriesChart using the specified container path.")

# 1. Get the Table component (sitting directly next to this button)
table = self.getSibling("Table")
selected_row_index = table.props.selection.selectedRow

# Ensure a row is actually highlighted
if selected_row_index is not None and selected_row_index >= 0:

    # 2. Extract the tag path safely from the highlighted table row
    row_data = table.props.data[selected_row_index]
    tag_to_remove = row_data["Tag Path"]

    # 3. Safely read the existing tags list as a true Python list
    current = list(self.view.custom.Tags) if self.view.custom.Tags else []

    # 4. If the selected tag exists in our list, clear it out
    if tag_to_remove in current:
        current.remove(tag_to_remove)
        self.view.custom.Tags = current

        # 5. Path navigating across the container layout to find the chart
        chart = self.getParent().getSibling("CoordinateContainer_0").getChild("FlexContainer").getChild("TimeSeriesChart")

        # Check if the chart component was successfully located
        if chart is not None:
            chart_plots = []

            # Loop through remaining tags to rebuild the plots configuration
            for t in current:
                tag_name = t.split("/")[-1]

                chart_plots.append({
                    "field": t,
                    "label": tag_name,
                    "type": "line",
                    "axis": "Default",
                    "style": {
                        "stroke": {
                            "width": 2
                        }
                    }
                })

            # --- SAFE SERIES INJECTION ---
            # Checks if series[0] exists. If not, creates it dynamically to prevent IndexError.
            if len(chart.props.series) > 0:
                chart.props.series[0].plots = chart_plots
            else:
                new_series = {
                    "name": "Trends",
                    "plots": chart_plots
                }
                chart.props.series = [new_series]

            # 6. Wipe out the table selection highlights so a deleted item doesn't look stuck
            table.props.selection.selectedRow = None
        else:
            system.util.getLogger("TrendRemoveButton").warn("Could not find TimeSeriesChart using the specified container path.")
